<script setup lang="ts">
import {computed} from 'vue'
import StatutoryWageSummary from './StatutoryWageSummary.vue'
import {useI18n} from 'vue-i18n'
import type {WageDisplay,PayrollLine} from '../payrollTypes'
import {hours} from '../time'
import {usePayrollText} from '../payrollText'
const props=defineProps<{line:WageDisplay&{issues?:string[];governance?:PayrollLine['governance']};hideGovernance?:boolean}>(),{locale}=useI18n(),{issue,r}=usePayrollText(),zh=computed(()=>locale.value.startsWith('zh'))
const tr=(a:string,b:string)=>zh.value?a:b
function componentLabel(item:WageDisplay['components'][number]){const key=({basic:'basicPay',overtime:'overtimePay',employee_cpf:'employeeCpf',employer_cpf:'employerCpf',sdl:'sdl'} as Partial<Record<string,Parameters<typeof r>[0]>>)[item.kind];return key?r(key):item.label}
function approvalLabel(state:string){const labels:Record<string,readonly [string,string]>={current:['核准有效','Current approval'],stale:['核准已过期','Stale approval'],missing:['尚未核准','Missing approval'],unavailable:['未保存核准证据','Approval evidence unavailable']};const label=labels[state];return label?tr(label[0],label[1]):tr('证据不足','Insufficient evidence')}
function governanceLabel(kind:string){const labels:Record<string,readonly [string,string]>={'legacy-valid':['安装前有效资料（无补造审批）','Installation baseline; no fabricated approval'],approved:['批准有效版本','Approved effective version'],'direct-adoption':['首次原样采用已发布版本','Initial unchanged published adoption'],'economic-unchanged':['经济内容未变化','Economic content unchanged'],default:['缺省输入（无手工金额）','Default input; no manual amounts']};return labels[kind]?tr(...labels[kind]):tr('来源证明不足','Insufficient source proof')}
const contract=computed(()=>props.line.hours?.basis==='contract'||props.line.rule?.generation?.mode==='contract')
const fixed=computed(()=>!contract.value&&(props.line.hours?.approvalState==='not_applicable'||props.line.rule?.generation?.mode==='fixed'))
</script>
<template><section class="wf-section wf-payroll-evidence"><StatutoryWageSummary :internal="hideGovernance?null:line.aw" :public-value="line.publicAw" :employee-view="hideGovernance"/><p v-for="code in line.issues||[]" :key="code" class="wf-issue" role="status">{{issue(code)}}</p><template v-if="!hideGovernance"><h3>{{tr('工资有效来源','Effective pay sources')}}</h3><template v-if="line.governance"><p v-for="(evidence,key) in line.governance" :key="key">{{key==='profile'?tr('个人方案','Profile'):tr('月度输入','Monthly input')}}: <template v-if="evidence">{{governanceLabel(evidence.kind)}} · {{evidence.subjectId}} / v{{evidence.version}}<span v-if="evidence.requestId"> · {{tr('申请／修订','Request / revision')}} {{evidence.requestId}} / {{evidence.revision}}</span></template><span v-else>{{tr('来源证明不足，当前工资须先处理阻断问题','Source evidence missing; resolve payroll blockers first')}}</span></p></template><p v-else>{{tr('旧快照未保存工资治理来源；不能据此认定已审批或legacy有效','Legacy snapshot has no governance evidence; approval or baseline validity cannot be inferred')}}</p></template><h3>{{tr('工时口径','Hours basis')}}</h3><template v-if="contract"><p>{{tr('按合同计发，出勤工时不适用','Paid under contract; attendance hours do not apply')}}</p><dl v-if="line.hours" class="wf-details"><dt>{{tr('合同计薪日 / 标准工作日','Contract payable days / standard working days')}}</dt><dd>{{line.hours.payableDays??'—'}} / {{line.hours.workingDays??'—'}}</dd><dt>{{tr('合同另计加班单位','Separately paid contract overtime units')}}</dt><dd>{{line.hours.overtimeSeconds==null?'—':hours(line.hours.overtimeSeconds)}}</dd></dl></template><p v-else-if="fixed">{{tr('固定全额，工时不适用','Full fixed salary; hours not applicable')}}</p><p v-if="!fixed&&line.hours&&line.hours.approvalState!=='current'&&line.issues?.some(code=>['APPROVAL_MISSING','APPROVAL_STALE','SOURCE_PENDING','AUTO_SCHEDULE_MISSING'].includes(code))" role="status">{{tr('待核准或证据不足；当前金额仅为阻断预览，不可确认为应付工资','Approval or evidence required; blocked preview amounts are not payable wages')}}</p><dl v-if="!fixed&&!contract&&line.hours" class="wf-details"><dt>{{tr('实际净工时','Actual net hours')}}</dt><dd>{{line.hours.actualSeconds==null?'—':hours(line.hours.actualSeconds)}}</dd><dt>{{tr('有效核准工时','Valid approved hours')}}</dt><dd>{{line.hours.approvedSeconds==null?tr('未核准或已过期','Missing or stale approval'):hours(line.hours.approvedSeconds)}} · {{approvalLabel(line.hours.approvalState)}}</dd><template v-if="line.hours.basis==='hourly'"><dt>{{tr('正常计薪 / 带薪假 / 加班','Normal / paid leave / overtime')}}</dt><dd>{{hours(line.hours.normalSeconds||0)}} / {{hours(line.hours.paidLeaveSeconds||0)}} / {{hours(line.hours.overtimeSeconds||0)}}</dd></template><template v-else><dt>{{tr('计薪日 / 工作日','Payable / working days')}}</dt><dd>{{line.hours.payableDays??'—'}} / {{line.hours.workingDays??'—'}}</dd></template></dl><p v-else-if="!fixed&&!contract">{{tr('旧快照未保存工时口径证据','Legacy snapshot has no hours evidence')}}</p><h3>{{tr('项目来源','Item evidence')}}</h3><details v-for="(item,index) in line.components" :key="index"><summary>{{componentLabel(item)}} · {{item.amount??tr('未知','Unknown')}}</summary><p v-if="item.lineage?.itemId.startsWith('legacy:')">{{tr('旧人工项目：仅有配置或当月输入，稳定编号及原始事件证据不足','Legacy manual item: configuration/input only; stable identity and original event evidence are unavailable')}}</p><dl v-if="item.lineage" class="wf-details"><dt>{{tr('来源 / 版本 / 月份','Origin / version / month')}}</dt><dd>{{item.lineage.origin}} · {{item.lineage.sourceId}} / v{{item.lineage.version}} · {{item.lineage.month}}</dd><dt>{{tr('项目编号 / 公式','Item / formula')}}</dt><dd>{{item.lineage.itemId}} · {{item.lineage.formula}}</dd><dt>{{tr('数量 / 单位 / 单价 / 倍率','Quantity / unit / rate / multiplier')}}</dt><dd>{{item.lineage.quantity}} {{item.lineage.unit}} · {{item.lineage.rate}} × {{item.lineage.multiplier}}</dd><dt>{{tr('折算 / 舍入','Proration / rounding')}}</dt><dd>{{item.lineage.proration}} · {{item.lineage.unroundedAmount}} → {{item.lineage.roundedAmount}} ({{item.lineage.rounding}})</dd><dt>{{tr('来源明细','Source references')}}</dt><dd>{{item.lineage.sourceKeys.join(' · ')}}</dd></dl><p v-else>{{tr('旧快照未保存项目级来源，证据不足','Legacy snapshot has no item evidence')}}</p></details></section></template>
